steps.script:
GameState.state["factions"]["1"].merge({"detachment": "Green Tide"}, true)
StratagemManager.load_faction_stratagems_for_player(1)
var i := 0
for m in GameState.state.units["U_CUSTODIAN_GUARD_A"].models:
	m["position"] = {"x": 808.0 + (i % 3) * 72.0, "y": 1420.0 + int(i / 3) * 72.0}
	i += 1
tree.current_scene._recreate_unit_visuals()
return StratagemManager.get_stratagem("faction_ork_green_tide_ere_we_go").get("implemented", false)

var p = PhaseManager.get_current_phase_instance()
if not p.has_pending_stratagem_window():
	return "none"
var ids := []
for o in p.get_pending_stratagem_window().get("offers", []):
	ids.append(str(o.get("stratagem_id", "")))
return ",".join(ids)

var p = PhaseManager.get_current_phase_instance()
var raw := -1
for d in p.dice_log:
	if str(d.get("type", "")) == "'ERE WE GO":
		raw = int(d.get("roll", -1))
var am = p.active_moves.get("U_BOYZ_B", {})
if raw < 1:
	return "no 'ERE WE GO dice-log entry"
if int(am.get("advance_roll", -1)) != raw + 2:
	return "advance roll %s, raw %d" % [str(am.get("advance_roll")), raw]
if absf(float(am.get("move_cap_inches", 0.0)) - (6.0 + raw + 2)) > 0.01:
	return "cap %s" % str(am.get("move_cap_inches"))
return "ok"
